/* func_lockstep.c - every matched routine (src/matched) held to the original.
 *
 *     func_lockstep [--states N] [--seed S] [--verbose] [--only MODULE:IP,...]
 *
 * Phase 2 replaces translated routines with hand-written C that must be
 * equal to the original, not similar. For each matched routine, the
 * module's image is placed in memory, the machine is put in N random states
 * (registers, flags, every byte of memory outside the image, with a return
 * address pushed that lies outside the routine), and the routine runs
 * twice: by the interpreter, instruction by instruction until it returns
 * there, and by the matched C. Everything is compared, as insn_lockstep
 * does for single instructions: registers, segments, IP, flags, the clock,
 * every byte written, every port touched (with the clock it was touched at)
 * and every interrupt raised. A port write that makes the machine look at
 * interrupts (pc.c wake()) must come within the run's limit and end the
 * body's run at the next boundary; a body stopped there by its own write has
 * completed its named region (wake_stop_reached).
 *
 * A state in which the original does not return within the step budget
 * (random data can send a loop a long way) is counted, not compared; so is
 * one the matched routine declines. Build with -DF117R_GEN_DIR.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "recomp_gen.h"
#include "reloc_image.h"
#include "matched.h"

/* ---- the CPU hooks: record, never emulate ---------------------------------
 * Port reads return a value derived from the port, width and count so far;
 * port accesses (with their clock) and interrupts are folded into a hash.
 * Both sides get identical hooks. The real run-time is linked in (matched
 * code calls it), so memory is compared and restored whole rather than by
 * tracked writes. */

/* The port and interrupt record, entry by entry, for the report of where two
 * sides part (the hash decides; this only says which access differs). */
typedef struct { uint8_t kind, width; uint16_t port; uint32_t val; uint64_t clk, h; } io_event;
#define IO_LOG 64

/* The machine's own wake on a port write (src/machine/pc.c io_write8): the
 * device state the decision depends on, from the machine's reset values
 * (PIT counters in access mode 3 with the low byte next, the PIC out of its
 * initialisation sequence). */
typedef struct { uint8_t pic_icw_step, pit_access[3], pit_hi_next[3]; } wake_model;

typedef struct {
    int      ndirty, overflow;
    uint32_t dirty[1];
    uint64_t io;            /* port writes and reads (with their clock), interrupts */
    uint64_t io_clocks;     /* separate so checking INT clocks does not change synthetic read answers */
    uint32_t nread;
    uint32_t nlog;
    io_event log[IO_LOG];
    wake_model dev;
} side_t;

static side_t g_side[2];

/* Keep historical program fixtures at their existing base. Overlays, drivers
 * and the COM launcher must not overlap the interrupt vector table. The
 * override provides a zero-base control and a second nonzero-base proof.
 * Keep the entire loaded code segment (including near fixture stubs) below
 * 20000h, where the graphics fixtures' page buffers start. Their RAM and
 * canonical 5000h/6000h stacks retain their original addresses and aliases. */
static const struct { const char *module; uint16_t base; } LOAD_BASES[] = {
    { "F117.COM", 0x0800 }, { "MGRAPHIC.EXE", 0x0800 }, { "MISC.EXE", 0x0800 },
    { "ASOUND.117", 0x0800 }, { "ISOUND.117", 0x0800 }, { "RSOUND.117", 0x0800 },
    { "ASOUND.LOG", 0x0800 }, { "ISOUND.LOG", 0x0800 }, { "RSOUND.LOG", 0x0800 },
};
static int fixture_base_valid(int base)
{
    return base == -1 || base == 0 || (base >= 0x0400 && base <= 0x0800);
}
static uint16_t module_load_base(const char *name, int forced)
{
    for (unsigned k=0;k<sizeof LOAD_BASES/sizeof LOAD_BASES[0];k++)
        if (!strcmp(name,LOAD_BASES[k].module)) return forced >= 0 ? (uint16_t)forced : LOAD_BASES[k].base;
    return 0;
}
static uint8_t g_loaded_image[MEM_SIZE]; /* relocated reference before fixtures */

/* A fresh port record and device model, for a run from the entry state. */
static void side_io_reset(side_t *s)
{
    s->io = 0; s->io_clocks = 0; s->nread = 0; s->nlog = 0;
    memset(&s->dev, 0, sizeof s->dev);
    for (int ch = 0; ch < 3; ch++) s->dev.pit_access[ch] = 3;
}

/* Special fixtures and return boundaries belong to a module-relative entry,
 * never to an IP shared by unrelated overlays. */
static const recomp_override *g_entry;
static int entry_is(const char *module, uint16_t seg, uint16_t ip)
{
    return g_entry && g_entry->seg == seg && g_entry->ip == ip && !strcmp(g_entry->module, module);
}

