static int patched_far_jump_row(const char *module, uint16_t seg, uint16_t ip)
{
    for (unsigned k = 0; k < sizeof PATCHED_FAR_JUMPS / sizeof PATCHED_FAR_JUMPS[0]; k++)
        if (PATCHED_FAR_JUMPS[k].seg == seg && PATCHED_FAR_JUMPS[k].ip == ip && !strcmp(PATCHED_FAR_JUMPS[k].module, module)) return 1;
    return 0;
}

static side_t *side_of(cpu_t *c) { return (side_t *)c->user; }

static uint64_t mix(uint64_t h, uint64_t v)
{
    h ^= v + 0x9E3779B97F4A7C15ull + (h << 6) + (h >> 2);
    return h * 0x100000001B3ull;
}

static void io_note(side_t *s, uint8_t kind, uint16_t port, int width, uint32_t val, uint64_t clk)
{
    s->io_clocks = mix(s->io_clocks, clk);
    if (s->nlog < IO_LOG) {
        io_event *e = &s->log[s->nlog];
        e->kind = kind; e->port = port; e->width = (uint8_t)width; e->val = val; e->clk = clk; e->h = s->io;
    }
    s->nlog++;
}

/* A partial run may have only a prefix of the original's I/O. A changed
 * event or an extra event is already a difference, even if the continuation
 * cannot return. Do not turn that evidence into an unfinished-state skip. */
static int io_prefix_changed(void)
{
    const side_t *a = &g_side[0], *b = &g_side[1];
    if (b->nlog > a->nlog || (b->nlog == a->nlog &&
        (b->io != a->io || b->io_clocks != a->io_clocks))) return 1;
    unsigned common = a->nlog < b->nlog ? a->nlog : b->nlog;
    if (common > IO_LOG) common = IO_LOG;
    for (unsigned k = 0; k < common; k++) {
        const io_event *x = &a->log[k], *y = &b->log[k];
        if (x->kind != y->kind || x->width != y->width || x->port != y->port ||
            x->val != y->val || x->clk != y->clk || x->h != y->h) return 1;
    }
    return 0;
}

/* Whether a byte written to a port makes the machine look at interrupts at
 * the next instruction boundary (pc.c wake(): cpu.stop_at = 0), with the
 * device state that decides it. Ports A0h/A1h (no second PIC is modelled),
 * the keyboard read at 60h and the OPL schedule (replay only) are not wakes
 * of a port write here, as they are not in the machine. */
static int port_wakes(wake_model *d, uint16_t port, uint8_t v)
{
    switch (port) {
    case 0x20:
        if (v & 0x10) { d->pic_icw_step = (v & 1) ? 3 : 2; return 0; }   /* ICW1 */
        if ((v & 0x18) == 0x08) return 0;                                 /* OCW3 */
        return 1;                                                         /* OCW2 (EOI) */
    case 0x21:
        if (d->pic_icw_step) { d->pic_icw_step--; return 0; }            /* ICW2-4 */
        return 1;                                                         /* the mask */
    case 0x40: case 0x41: case 0x42: {
        const int ch = port - 0x40;
        int loaded = 1;                                                   /* access 1 or 2: one byte loads */
        if (d->pit_access[ch] != 1 && d->pit_access[ch] != 2) {
            loaded = d->pit_hi_next[ch];                                  /* low then high: the high byte loads */
            d->pit_hi_next[ch] ^= 1;
        }
        return loaded && ch == 0;
    }
    case 0x43: {
        const int ch = (v >> 6) & 3;
        if (ch == 3 || (v & 0x30) == 0) return 0;                         /* read-back, latch command */
        d->pit_access[ch] = (uint8_t)((v >> 4) & 3);
        d->pit_hi_next[ch] = 0;
        return ch == 0;
    }
    default:
        return 0;
    }
}

/* The first wake of the run a matched body makes (side 1, between
 * wake_arm and wake_overrun): the original stops at the boundary after
 * that instruction, so the body must have stopped there too. */
static struct { int armed, woke, by_body; uint64_t clk, limit; uint16_t port, flags; uint8_t val; } g_wake;
static cpu_t *g_wake_cpu;   /* the matched side's CPU */
static int g_runner_depth;  /* original code the body called is running (step_runner), not the body's own C */

static void io_w(cpu_t *c, uint16_t port, uint32_t val, int width)
{
    side_t *s = side_of(c);
    /* The clock at the access is part of the record: a body that charges
     * its instructions in one lump around a port access puts the access at
     * another clock than the original, though it ends at the same one. */
    s->io = mix(s->io, 0x1000000ull | ((uint64_t)port << 8) | (uint64_t)width);
    s->io = mix(s->io, val);
    s->io = mix(s->io, c->icount);
    io_note(s, 1, port, width, val, c->icount);
    for (int b = 0; b < width; b++) {   /* a word goes out as two bytes, as pc_io_write sends it */
        const uint16_t p = (uint16_t)(port + b);
        const uint8_t v = (uint8_t)(val >> (8 * b));
        if (!port_wakes(&s->dev, p, v)) continue;
        if (c == g_wake_cpu && g_wake.armed && !g_wake.woke) {   /* the limit as it was before the write lowers it */
            g_wake.woke = 1; g_wake.clk = c->icount; g_wake.limit = c->stop_at; g_wake.by_body = g_runner_depth == 0;
            g_wake.port = p; g_wake.val = v; g_wake.flags = c->flags;        }
        cpu_irq_state_changed(c);
    }
}

static uint64_t g_io_salt;   /* private hunk: a fixture varies the port-read answers per state (they are otherwise a function of the port, width and read count only) */
static unsigned g_probe_tail;
static unsigned g_decline_floor;   /* private hunk (bo-0F98): a fixture states the first block's room; the mid-run stop then lands at 0 or 1 clocks of room half the time and the body must decline below the floor and run at or above it */
/* private hunk (ASOUND.117 0BB5 room probe): a fixture lists the clocks where its body's blocks start (g_room_at) with each
 * block's claim (g_room_need). Half of the mid-run stops then land at 0..need clocks of room at one of those blocks, and a
 * body that hands back at a listed block with at least the block's claim of room left (an over-claim) is a mismatch. */
static unsigned g_room_n, g_room_at[16], g_room_need[16];
static uint16_t g_room_ip[16];
static unsigned g_room_probe_n, g_room_probe_k[8], g_room_probe_e[8];   /* private hunk (ASOUND.117 030B): room-claim probe limits and the stop clock each must give */
static unsigned g_probe_sweep;   /* private hunk (RSOUND.LOG 00FD): the mid-run stop is k = (s >> 2) mod steps, so every clock of the path is stopped at */
static unsigned g_probe_sweep_all;   /* private hunk (ASOUND.117 036B): one state in 16 sweeps the mid-run stop over every clock of its path */
static int g_int1a_by_vector;   /* private hunk (ISOUND.LOG 0082): the fixture sends INT 1Ah through the vector table instead of the native answer */
static unsigned g_probe_steps;  /* private hunk: a fixture sets the limit probe's original instruction count (0 = the original's own count) */   /* private hunk: a fixture asks for mid-run stops near the end of the path */
static unsigned g_io_force_n, g_io_force_bit7, g_io_force_after;   /* private hunk: a fixture forces the status bit 7 of the first byte port reads (status polls)  */
/* private hunk (batch bg): a fixture may force bits of the answers read from up to two ports: answer = (hash & and) | or, so a status wait can be made to time out. */
static struct { uint16_t port; uint16_t and_, or_; } g_io_force[2];
static unsigned g_cap_hint;   /* private hunk (batch bg): a fixture raises the step cap of its state (a 65535-pass wait loop takes 330000 instructions) */
static uint32_t io_r(cpu_t *c, uint16_t port, int width)
{
    side_t *s = side_of(c);
    s->nread++;
    s->io = mix(s->io, 0x2000000ull | ((uint64_t)port << 8) | (uint64_t)width);
    s->io = mix(s->io, c->icount);
    uint64_t v = mix((uint64_t)port * 31u + (uint64_t)width + g_io_salt, s->nread);
    if (width == 1 && g_io_force_n && s->nread <= (uint32_t)g_io_force_n + (g_io_force_after ? 1u : 0u)) {   /* private hunk: the first n byte reads have bit 7 = g_io_force_bit7, read n+1 the opposite when g_io_force_after */
        const unsigned bit7 = s->nread <= (uint32_t)g_io_force_n ? g_io_force_bit7 : !g_io_force_bit7;
        v = (v & 0x7Full) | (bit7 ? 0x80ull : 0);
    }
    for (int f_ = 0; f_ < 2; f_++)
        if (g_io_force[f_].port == port && (g_io_force[f_].and_ || g_io_force[f_].or_)) v = (v & g_io_force[f_].and_) | g_io_force[f_].or_;
    io_note(s, 2, port, width, 0, c->icount);
    return width == 1 ? (uint32_t)(v & 0xFF) : (uint32_t)(v & 0xFFFF);
}

static int g_checked_alloc;
static unsigned long long g_alloc_errors;
static unsigned long long g_gradient_full;
static unsigned long long g_sprite_zero, g_sprite_skip;
static unsigned long long g_iret_full, g_iret_special;
static int g_dos;                  /* the routine under test is in DOS_STUBS: INT 21h is answered here */
static struct { uint16_t ax; uint8_t cf; uint16_t put; } g_dos_script[16];   /* a fixture may fix the first answers of INT 21h (AX, CF);
                                                                               put 100h|b: a read (3Fh) stores byte b at DS:DX */
static unsigned g_dos_script_n;

/* Scoped BIOS tick and DOS vector answers supplied by the entry fixtures. */
static int g_native_int1a;
static uint16_t g_int1a_cx, g_int1a_dx;
static uint8_t g_int1a_al;
static int g_vector_force;
static uint16_t g_vector_segment, g_vector_offset;

static int g_native_int10;   /* answer INT 10h too (the string writer under test) */
static int g_int10_force;    /* private hunk: a fixture sets AL for INT 10h function 0Fh (get video mode) per state */
static uint8_t g_int10_al;
static int g_kbd_force;      /* a fixture sets the answer (AX and ZF/CF) of INT 16h and INT 21h per state */
static uint16_t g_kbd_ax, g_kbd_fl;
static int int_h(cpu_t *c, uint8_t vec)
{
    side_t *s = side_of(c);
    s->io = mix(s->io, 0x3000000ull | vec);
    for (int i = 0; i < 8; i++) s->io = mix(s->io, c->r[i]);
    for (int i = 0; i < 4; i++) s->io = mix(s->io, c->seg[i]);
    s->io = mix(s->io, ((uint64_t)c->ip << 16) | c->flags);
    io_note(s, 3, vec, 0, c->r[R_AX], c->icount);
    if (g_kbd_force && (vec == 0x16 || vec == 0x21)) { s->nread++; c->r[R_AX] = g_kbd_ax; c->flags = (uint16_t)((c->flags & ~(F_CF | F_ZF)) | (g_kbd_fl & (F_CF | F_ZF))); return 1; }
    if (g_vector_force && vec == 0x21 && get_r8(c,R_AH) == 0x35) { s->nread++; c->seg[S_ES]=g_vector_segment; c->r[R_BX]=g_vector_offset; return 1; }
    if (g_dos && vec == 0x21) {     /* a DOS that answers: AX (and DX), and CF one time in four */
        s->nread++;
        const uint8_t ah_in = get_r8(c, R_AH);
        const uint16_t dx_in = c->r[R_DX];
        const uint64_t v = mix(s->io, s->nread);   /* (the record so far is the same on both sides) */
        const int alloc = g_checked_alloc && get_r8(c, R_AH) == 0x48;
        const int wide = get_r8(c, R_AH) == 0x42 || ((v >> 56) & 3) == 1;
        c->r[R_AX] = (uint16_t)(v >> 16);
        if (((v >> 58) & 3) == 0) set_r8(c, R_AL, 0);  /* AL 0 (success, found) one time in four */
        if (alloc) c->r[R_AX] = (v & 1) ? 8 : 0x197A;
        if (wide) c->r[R_DX] = (uint16_t)(v >> 32);
        set_flag(c, F_CF, ((v >> 60) & 3) == 0);
        if (s->nread <= g_dos_script_n) {
            c->r[R_AX] = g_dos_script[s->nread - 1].ax; set_flag(c, F_CF, g_dos_script[s->nread - 1].cf);
            if ((g_dos_script[s->nread - 1].put & 0x100) && ah_in == 0x3F)   /* the byte a read brings */
                mem_write8(c, phys(c->seg[S_DS], dx_in), (uint8_t)g_dos_script[s->nread - 1].put);
        }
        return 1;
    }
    /* For every other routine, DOS (21h) and the BIOS keyboard (16h) answer here,
     * as port reads do: AX from the call count (a small value one time in four),
     * and a random carry and zero flag, so both outcomes of a call are reached.
     * Through the vector table (the image's first bytes here) a routine's DOS
     * call went off into the image and only the routes could check what follows. */
    if (vec == 0x21 || vec == 0x16) {
        s->nread++;
        const uint64_t v = mix(0x4000000ull | vec, s->nread);
        c->r[R_AX] = (v & 0x300) ? (uint16_t)(v >> 16) : (uint16_t)((v >> 16) & 3);
        c->flags = (uint16_t)((c->flags & ~(F_CF | F_ZF)) | ((v & 0x400) ? F_CF : 0) | ((v & 0x800) ? F_ZF : 0));
        return 1;
    }
    if (vec == 0x1A && g_native_int1a && get_r8(c,R_AH) == 0) { s->nread++; c->r[R_CX]=g_int1a_cx; c->r[R_DX]=g_int1a_dx; set_r8(c,R_AL,g_int1a_al); return 1; }
    if (vec == 0x1A && g_native_int1a && get_r8(c,R_AH) == 2) { s->nread++; c->r[R_CX]=g_int1a_cx; c->r[R_DX]=g_int1a_dx; set_flag(c, F_CF, 0); return 1; }
    if (vec == 0x33) {              /* the mouse driver: reset answers FFFFh or 0; function 3 gives buttons 0-7, column, row */
        s->nread++;
        const uint64_t v = mix(0x5000000ull | vec, s->nread);
        if (c->r[R_AX] == 3) { c->r[R_BX] = (uint16_t)(v & 7); c->r[R_CX] = (uint16_t)(v >> 8); c->r[R_DX] = (uint16_t)(v >> 24); }
        else if (c->r[R_AX] == 0) c->r[R_AX] = (v & 0x100) ? 0xFFFF : 0;
        return 1;
    }
    if (vec == 0x10 && g_native_int10) { s->nread++; if (g_int10_force && get_r8(c, R_AH) == 0x0F) set_r8(c, R_AL, g_int10_al); return 1; }   /* the BIOS video calls leave the registers alone (private hunk: or answer the video mode in AL) */
    return 0;                       /* not emulated: the CPU dispatches it */
}

/* ---- random states -------------------------------------------------------- */

static uint64_t g_rng;
static uint64_t rnd(void)
{
    g_rng ^= g_rng << 13; g_rng ^= g_rng >> 7; g_rng ^= g_rng << 17;
    return g_rng;
}

/* Each routine draws from a stream of its own, from the run's seed and the
 * routine's module and address (splitmix64 over an FNV-1a of the name): its
 * states do not move when other routines are added, and shards of the table
 * (--shard) can run apart and still test what one run would. */
static uint64_t routine_seed(uint64_t seed, const recomp_override *o)
{
    uint64_t h = 0xCBF29CE484222325ULL;
    for (const char *p = o->module; *p; p++) h = (h ^ (uint8_t)*p) * 0x100000001B3ULL;
    uint64_t z = seed ^ h ^ ((uint64_t)o->seg << 16 | o->ip);
    z += 0x9E3779B97F4A7C15ULL;
    z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9ULL;
    z = (z ^ (z >> 27)) * 0x94D049BB133111EBULL;
    return (z ^ (z >> 31)) | 1;
}

static uint8_t *g_pristine, *g_mem[2];
static cpu_t g_cpu[2];
/* Only the authored zero-count binding case exceeds the usual guard. */
static unsigned g_step_cap = 100000;
/* private probe (MPS_LOGO 00DA:0307 room probes): when set, setup_side gives the state stop_at = icount + g_stop_delta. */
static int g_stop_delta_on;
static unsigned g_stop_delta;
/* Authored cases also run at s % 4 == 1, where mid-run stops are probed. */
static int g_fixture_args;

static void restore(void)
{
    for (int k = 0; k < 2; k++) {
        side_t *s = &g_side[k];
        for (int i = 0; i < s->ndirty; i++) g_mem[k][s->dirty[i]] = g_pristine[s->dirty[i]];
        if (s->overflow) memcpy(g_mem[k], g_pristine, MEM_SIZE);
        s->ndirty = 0; s->overflow = 0;
        side_io_reset(s);
    }
}

static void set_state(cpu_t *c, uint16_t cs, uint16_t ip, const uint16_t *r, const uint16_t *seg, uint16_t flags)
{
    memcpy(c->r, r, sizeof c->r);
    memcpy(c->seg, seg, sizeof c->seg);
    c->seg[S_CS] = cs;
    c->ip = ip;
    c->op_ip = ip;
    c->op_cs = cs;
    c->flags = flags;
    c->seg_override = -1;
    c->rep_prefix = 0;
    c->halted = 0;
    c->icount = 1000;
    c->stop_at = 1001;
    c->inhibit_at = 0;
    c->int_depth = 0;
}

/* Interrupt handlers (kind 3) that advance the saved IP before IRET: the
 * frame holds back - advance, so a state that resumes at `back` returned
 * through the handler. Half the states save the faulting instruction's IP
 * (fault), the one value that selects the handler's other denominator. */
typedef struct { uint16_t seg, ip, advance, fault; } interrupt_frame_fixture;
static const interrupt_frame_fixture INTERRUPT_FRAMES[] = {
    { 0x0FB2, 0x084E, 4, 0x07C8 },        /* span divide error: idiv [261D] */
    { 0x120A, 0x0971, 3, 0x0A3E },        /* perspective divide error: the faulting divide is three bytes */
};
static const interrupt_frame_fixture *interrupt_frame(const recomp_override *o)
{
    if (o->matched != 3 || strcmp(o->module, "VGAME.EXE")) return NULL;
    for (unsigned k = 0; k < sizeof INTERRUPT_FRAMES / sizeof INTERRUPT_FRAMES[0]; k++)
        if (o->seg == INTERRUPT_FRAMES[k].seg && o->ip == INTERRUPT_FRAMES[k].ip)
            return &INTERRUPT_FRAMES[k];
    return NULL;
}

/* Entry points inside a function whose frame is already built (a loop's continue point the
 * function's own arms jump back to, or the second half of a routine another matched body hands
 * back to): the return address the harness pushes is the frame's, and the routine starts `frame`
 * bytes below it (saved BP, locals, saved registers), which the fixture fills, so its own pushes
 * do not overwrite locals it reads later. Its RET still comes with SP back at the return address. */
static const struct { const char *module; uint16_t seg, ip, frame; } LIVE_FRAMES[] = {
    { "SETUP.EXE", 0x0237, 0x0094, 0x000E }, /* joystick poll after its STI, in 005C's frame: seven saved registers */
    { "RSOUND.LOG", 0x0000, 0x027C, 0x0002 },   /* timer installer's tail: the AX saved at 0266 sits under the return address */
    { "RSOUND.LOG", 0x0000, 0x0289, 0x0002 },   /* timer installer's tail: the AX saved at 0266 sits under the return address */
    { "END.EXE", 0x0000, 0x34EA, 0x0012 },   /* debrief score step: saved BP, 0Eh bytes of locals, SI */
    { "END.EXE", 0x0000, 0x099D, 0x000E },   /* icon placement in 0880's frame: 8 bytes of locals, DI, SI */
    { "VGAME.EXE", 0x0000, 0x4657, 0x0008 }, /* countermeasure release in 462E's frame (ENTER 6,0) */
    { "START.EXE", 0x0000, 0x0B49, 0x0006 }, /* arms hover change in 0B01's frame: saved BP, the item, SI */
    { "END.EXE", 0x0000, 0x2430, 0x0010 },   /* ribbon draw in 23D6's frame: saved BP, 0Eh bytes of locals */
    { "END.EXE", 0x0000, 0x36D6, 0x0004 },   /* death message box draw in 3682's frame: saved BP, one local word */
    { "PLAYER.EXE", 0x0000, 0x22AF, 0x0006 },/* raise()'s exit(3) tail in 223A's frame: saved BP, 4 bytes of locals */
    { "ASOUND.LOG", 0x0000, 0x00FA, 0x0002 },
    { "ASOUND.LOG", 0x0000, 0x0423, 0x0002 },
    { "ASOUND.LOG", 0x0000, 0x042C, 0x0002 },
};

/* The routine's entry state: registers, and the stack as a caller leaves it
 * (for an interrupt handler, as the CPU's interrupt entry leaves it). */
static void setup_side(cpu_t *c, const recomp_override *o, uint16_t cs, uint16_t ip, const uint16_t *r,
                       const uint16_t *seg, uint16_t flags, uint16_t back, int s, const uint16_t *small)
{
    set_state(c, cs, ip, r, seg, flags);
    const interrupt_frame_fixture *frame = interrupt_frame(o);
    if (o->matched == 3) {                                     /* FLAGS, CS, IP; IF and TF cleared */
        c->r[R_SP] = (uint16_t)(c->r[R_SP] - 2);
        seg_write16(c, c->seg[S_SS], c->r[R_SP], flags);
        c->flags = (uint16_t)(c->flags & (0xFFFFu ^ (F_IF | F_TF)));
        c->int_depth = 1 + ((s >> 3) & 1);                     /* IRET's depth step, nested or not */
    }
    c->r[R_SP] = (uint16_t)(c->r[R_SP] - 2);
    if (o->matched >= 2) {                                     /* far or interrupt: CS too */
        seg_write16(c, c->seg[S_SS], c->r[R_SP], cs);
        c->r[R_SP] = (uint16_t)(c->r[R_SP] - 2);
    }
    seg_write16(c, c->seg[S_SS], c->r[R_SP], (uint16_t)(back - (frame ? frame->advance : 0)));
    /* Half the states put small arguments above it: random words
     * almost never reach a routine's edge cases (zero, -1, 1). */
    const uint16_t args = o->matched == 3 ? 6 : o->matched == 2 ? 4 : 2;   /* above IP, CS, FLAGS */
    for (int a = 0; a < 4 && ((s & 2) || g_fixture_args); a++)
        seg_write16(c, c->seg[S_SS], (uint16_t)(c->r[R_SP] + args + 2 * a), small[a]);
    for (unsigned k = 0; k < sizeof LIVE_FRAMES / sizeof LIVE_FRAMES[0]; k++)
        if (!strcmp(LIVE_FRAMES[k].module, o->module) && LIVE_FRAMES[k].seg == o->seg && LIVE_FRAMES[k].ip == o->ip)
            c->r[R_SP] = (uint16_t)(c->r[R_SP] - LIVE_FRAMES[k].frame);
    c->stop_at = c->icount + (g_stop_delta_on ? g_stop_delta : g_step_cap);
}

static unsigned long long g_overrun;    /* routines that ran past the event limit */

